def confirm_existing(apps, schema_editor):
    # Every handover recorded before the kiosk was made at the office counter,
    # so it is already confirmed. Without this the Key Register would ask the
    # Admin to confirm the whole history.
    KeyHandover = apps.get_model("bookings", "KeyHandover")
    KeyHandover.objects.filter(issued_at__isnull=False).update(
        issue_confirmed_at=F("issued_at"), issue_confirmed_by=F("issued_by")
    )
    KeyHandover.objects.filter(returned_at__isnull=False).update(
        return_confirmed_at=F("returned_at"), return_confirmed_by=F("returned_to")
    )


